using System;
using System.Linq;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using QuickCode.QuickCode.Infrastructure.Integration.Helpers;
using QuickCode.QuickCode.Infrastructure.Integration.Nswag;
using QuickCode.QuickCode.Infrastructure.Integration.Nswag.Clients.IdentityModuleApi.Contracts;
using QuickCode.QuickCode.Portal.Helpers;
using QuickCode.QuickCode.Portal.Models;

namespace QuickCode.QuickCode.Portal.ViewComponents
{
    public class UserOperation : ViewComponent
    {
        private readonly IAspNetUsersClient _usersClient;
        private readonly IHttpContextAccessor _httpContextAccessor;

        public UserOperation(IAspNetUsersClient usersClient, IHttpContextAccessor httpContextAccessor)
        {
            _usersClient = usersClient;
            _httpContextAccessor = httpContextAccessor;
            ApplyBearerToken();
        }

        public async Task<IViewComponentResult> InvokeAsync()
        {
            var userDetail = new UserDetail
            {
                NameSurname = "User",
                ImageUrl = PortalUserPhoto.DefaultUrl,
                GroupName = "User"
            };

            var principal = HttpContext.User;
            if (principal.Identity?.IsAuthenticated != true)
                return View(userDetail);

            userDetail.NameSurname = principal.FindFirst(ClaimTypes.Name)?.Value ?? "User";
            userDetail.GroupName = principal.FindFirst(ClaimTypes.GroupSid)?.Value ?? "User";
            userDetail.ImageUrl = principal.FindFirst(PortalUserPhoto.ClaimType)?.Value
                                  ?? PortalUserPhoto.DefaultUrl;

            var email = principal.FindFirst(ClaimTypes.Email)?.Value;
            if (string.IsNullOrWhiteSpace(email))
                return View(userDetail);

            try
            {
                var userData = await _usersClient.AspNetUsersGetUserAsync(email);
                userDetail.ImageUrl = PortalUserPhoto.FromObject(userData);
            }
            catch
            {
                // Keep claim / default photo if Identity is unavailable.
            }

            return View(userDetail);
        }

        private void ApplyBearerToken()
        {
            var httpContext = _httpContextAccessor.HttpContext;
            if (httpContext?.User.Identity?.IsAuthenticated != true)
                return;

            var accessToken = PortalApiTokenStore.GetAccessToken(httpContext);
            if (!string.IsNullOrEmpty(accessToken))
                ((ClientBase)_usersClient).SetBearerToken(accessToken);
        }
    }
